algorithms.pseudocode:
function dispatch_rename(dest_reg: int, rob_idx: uint14):
    if dest_reg < 65:
        reg_tracking_table[dest_reg].valid = 0
        reg_tracking_table[dest_reg].payload = rob_idx & 0x3FFF
        reg_tracking_table[dest_reg].decay_ctr = 0

function writeback_complete(dest_reg: int, rob_idx: uint14, val: uint64, reg_type: enum):
    if dest_reg < 65:
        entry = reg_tracking_table[dest_reg]
        // Only overwrite if this instruction is the latest writer to the logical register
        if entry.valid == 0 and entry.payload == (rob_idx & 0x3FFF):
            digest = generate_digest(val, reg_type)
            entry.payload = uint14(digest) & 0x0FFF
            entry.valid = 1
            entry.decay_ctr = 0
            reg_tracking_table[dest_reg] = entry

function decay_tick():
    for r in 0 .. 64:
        if reg_tracking_table[r].valid == 1:
            if reg_tracking_table[r].decay_ctr >= 255:
                reg_tracking_table[r].valid = 0
            else:
                reg_tracking_table[r].decay_ctr += 1

function predict(pc: uint64) -> (int32, array of int, array of int):
    sR_sum = 0
    selected_regs = array of 8 ints, initialized to -1
    sampled_regs = array of 8 ints, initialized to -1

    for bank in 0 .. 7:
        idx0 = hash_pc(pc, 0, bank) % 8
        idx1 = hash_pc(pc, 1, bank) % 8
        idx2 = hash_pc(pc, 2, bank) % 8

        // Determine register candidates in this bank (r % 8 == bank)
        bank_regs = [r for r in 0 .. 64 if (r % 8) == bank]
        valid_regs = [r for r in bank_regs if reg_tracking_table[r].valid == 1]

        if valid_regs is empty:
            continue

        // Sample one available register randomly for training update
        sampled_regs[bank] = random_choice(valid_regs)

        // Find register with maximum usefulness in this bank
        max_usefulness = -1000000
        best_reg = -1
        for r in valid_regs:
            // Index into vector entry corresponding to register r
            u = sR_UT[bank].UT0[idx0][r] + sR_UT[bank].UT1[idx1][r] + sR_UT[bank].UT2[idx2][r]
            if u > max_usefulness:
                max_usefulness = u
                best_reg = r

        selected_regs[bank] = best_reg

        // Gated prediction contribution: scale by 2.5 if useful, 0 otherwise
        if max_usefulness > 0 and best_reg != -1:
            digest = reg_tracking_table[best_reg].payload & 0x0FFF
            h0 = hash_wt(pc, digest, 0) % 512
            h1 = hash_wt(pc, digest, 1) % 256
            h2 = hash_wt(pc, digest, 2) % 128

            bank_weight = sR_WT[bank].WT0[h0] + sR_WT[bank].WT1[h1] + sR_WT[bank].WT2[h2]
            sR_sum += int32(bank_weight * 2.5)
        else:
            sR_sum += 0

    return (sR_sum, selected_regs, sampled_regs)

function sat_update(val: int, delta: int, min_val: int, max_val: int) -> int:
    new_val = val + delta
    if new_val < min_val:
        return min_val
    if new_val > max_val:
        return max_val
    return new_val

function update(pc: uint64, taken: bool, sc_train_needed: bool, selected_regs: array of 8 ints, sampled_regs: array of 8 ints):
    if not sc_train_needed:
        return

    for bank in 0 .. 7:
        r_train = sampled_regs[bank]
        if r_train == -1:
            continue

        // 1. Train usefulness tables (UT) for the sampled register
        idx0 = hash_pc(pc, 0, bank) % 8
        idx1 = hash_pc(pc, 1, bank) % 8
        idx2 = hash_pc(pc, 2, bank) % 8

        // Get prediction with sampled register's digest
        digest = reg_tracking_table[r_train].payload & 0x0FFF
        h0 = hash_wt(pc, digest, 0) % 512
        h1 = hash_wt(pc, digest, 1) % 256
        h2 = hash_wt(pc, digest, 2) % 128
        pred_sign = (sR_WT[bank].WT0[h0] + sR_WT[bank].WT1[h1] + sR_WT[bank].WT2[h2]) >= 0

        useful_delta = (pred_sign == taken) ? +1 : -1
        sR_UT[bank].UT0[idx0][r_train] = sat_update(sR_UT[bank].UT0[idx0][r_train], useful_delta, -32, 31)
        sR_UT[bank].UT1[idx1][r_train] = sat_update(sR_UT[bank].UT1[idx1][r_train], useful_delta, -32, 31)
        sR_UT[bank].UT2[idx2][r_train] = sat_update(sR_UT[bank].UT2[idx2][r_train], useful_delta, -32, 31)

        // 2. Train Prediction Weight Tables (WT)
        weight_delta = taken ? +1 : -1
        sR_WT[bank].WT0[h0] = sat_update(sR_WT[bank].WT0[h0], weight_delta, -32, 31)
        sR_WT[bank].WT1[h1] = sat_update(sR_WT[bank].WT1[h1], weight_delta, -32, 31)
        sR_WT[bank].WT2[h2] = sat_update(sR_WT[bank].WT2[h2], weight_delta, -32, 31)

function squash_recovery(flushed_rob_mask: bitmask):
    for r in 0 .. 64:
        if reg_tracking_table[r].valid == 0:
            rob_idx = reg_tracking_table[r].payload
            // Check whether rob_idx is marked in flushed_rob_mask
            if ((flushed_rob_mask >> rob_idx) & 1) != 0:
                // Speculative producer instruction was squashed; invalidate tracking entry
                reg_tracking_table[r].valid = 0
                reg_tracking_table[r].payload = 0
                reg_tracking_table[r].decay_ctr = 0
